"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { Fragment, type ReactNode, useId, useState } from "react";

import { cn } from "@/lib/utils";

/** One place in the dock. The label names the icon and shows as a tip on hover or focus. */
export interface DockItem {
  id: string;
  label: string;
  icon: ReactNode;
}

/** Props for a dock. Pass `value` to control the active item, or `defaultValue` to let it hold its own. */
export interface DockProps {
  /** Names the dock for screen readers, for example "Workspace". */
  label: string;
  /** Items in groups. A thin rule separates one group from the next. */
  groups: DockItem[][];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
}

// Damping 46 is 2 × √520, rounded up: critically damped, so the pill arrives without wobble.
const GLIDE: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const INSTANT: Transition = { duration: 0 };

/**
 * Shows a row of icon places, such as the views of an app. A pill glides to the
 * place you choose, and each icon shows its name on hover or focus.
 */
export function Dock({ label, groups, value, defaultValue, onValueChange, className }: DockProps) {
  const [ownValue, setOwnValue] = useState(defaultValue ?? groups[0]?.[0]?.id);
  const active = value ?? ownValue;
  const reduceMotion = useReducedMotion();
  // Each dock needs its own layout id, or two docks on one page would pass one pill between them.
  const layoutId = useId();
  // Escape hides the name tips until the pointer or the focus moves on, so a tip never traps what it covers.
  const [tipsHidden, setTipsHidden] = useState(false);

  const select = (id: string) => {
    if (value === undefined) setOwnValue(id);
    onValueChange?.(id);
  };

  // The dock never scrolls: a scrolling row would clip the tips above it. Keep
  // it to about six places so it fits a phone screen.
  return (
    <div
      role="group"
      aria-label={label}
      onKeyDown={(event) => {
        if (event.key === "Escape") setTipsHidden(true);
      }}
      onPointerLeave={() => setTipsHidden(false)}
      className={cn(
        "inline-flex items-center gap-1 rounded-2xl border border-border bg-card p-1.5 shadow-sm",
        className,
      )}
    >
      {groups.map((group, index) => (
        <Fragment key={group[0]?.id ?? index}>
          {index > 0 ? <span aria-hidden="true" className="mx-1 h-6 w-px shrink-0 bg-border" /> : null}
          {group.map((item) => {
            const isActive = item.id === active;
            return (
              <button
                key={item.id}
                type="button"
                aria-label={item.label}
                aria-current={isActive || undefined}
                onClick={() => select(item.id)}
                onFocus={() => setTipsHidden(false)}
                onPointerEnter={() => setTipsHidden(false)}
                className={cn(
                  "group relative grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-xl outline-none motion-safe:transition-colors motion-safe:duration-200",
                  "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
                  isActive ? "text-foreground" : "text-muted-foreground hover:text-foreground",
                )}
              >
                {isActive ? (
                  <motion.span
                    layoutId={layoutId}
                    aria-hidden="true"
                    transition={reduceMotion ? INSTANT : GLIDE}
                    className="absolute inset-0 rounded-xl bg-muted"
                  />
                ) : null}
                <span
                  aria-hidden="true"
                  className="relative inline-flex size-5 items-center justify-center motion-safe:transition-transform motion-safe:duration-150 group-active:scale-90"
                >
                  {item.icon}
                </span>
                {/* The tip repeats the accessible name for sighted users, so it stays hidden from screen readers.
                    It stays open while the pointer moves onto it: the transparent strip below it bridges the gap. */}
                {tipsHidden ? null : (
                  <span
                    aria-hidden="true"
                    className="invisible absolute bottom-full left-1/2 mb-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background opacity-0 before:absolute before:inset-x-0 before:top-full before:h-2 group-hover:visible group-hover:opacity-100 group-focus-visible:visible group-focus-visible:opacity-100 motion-safe:transition motion-safe:duration-150"
                  >
                    {item.label}
                  </span>
                )}
              </button>
            );
          })}
        </Fragment>
      ))}
    </div>
  );
}
